"""Small deterministic metrics for already aligned mono float samples."""
import math
def compare(reference,test):
    n=min(len(reference),len(test));x=reference[:n];y=test[:n]
    energy=sum(v*v for v in x);error=sum((a-b)**2 for a,b in zip(x,y))
    dot=sum(a*b for a,b in zip(x,y));scale=dot/energy if energy else 0
    projected=sum((scale*a)**2 for a in x);residual=sum((b-scale*a)**2 for a,b in zip(x,y))
    seg=[]
    for at in range(0,n-319,320):
        e=sum(a*a for a in x[at:at+320]);noise=sum((a-b)**2 for a,b in zip(x[at:at+320],y[at:at+320]))
        if e>1e-8:seg.append(max(-10,min(35,10*math.log10(e/max(noise,1e-30)))))
    return {'samples':n,'snr_db':10*math.log10(energy/error) if energy and error else None,
            'si_sdr_db':10*math.log10(projected/residual) if projected and residual else None,
            'segmental_snr_db':sum(seg)/len(seg) if seg else None,
            'mse':error/max(n,1),'max_absolute_error':max((abs(a-b) for a,b in zip(x,y)),default=0)}
"}

