   const page=await context.newPage();pages[role]=page;page.on('pageerror',e=>errors.push(role+':'+e.message));
   await page.goto(`http://127.0.0.1:${port}/?api=1&touch=1&kiosk=1`,{waitUntil:'networkidle'});
   await page.waitForFunction(()=>typeof state!=='undefined'&&state?.pair.phase==='ready');
   await page.screenshot({path:path.join(out,role+'_overview.png')});
   results[role]={idle:await page.evaluate(()=>state)};
   for(const view of ['nodes','channels','calls','monitor','events','settings']){
    await page.evaluate(v=>navigate(v),view);
    await page.screenshot({path:path.join(out,role+'_'+view+'.png')});
    const bounds=await page.locator('[data-action=call]').evaluateAll(bs=>bs.map(b=>{const r=b.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height,visible:r.bottom<=720&&r.left>=0&&r.right<=1280}}));
    results[role][view+'_buttons']=bounds;
   }
   await page.evaluate(()=>navigate('calls'));
  }
  await pages[initiator].locator('[data-action=call]').click();
  for(const role of ['master','slave'])await pages[role].waitForFunction(()=>state.pair.phase==='in_call',{},{timeout:20000});
  await new Promise(r=>setTimeout(r,11000));
  for(const role of ['master','slave']){
   results[role].in_call=await pages[role].evaluate(()=>state);
   await pages[role].screenshot({path:path.join(out,role+'_active.png')});
   if(results[role].in_call.link.received<60||results[role].in_call.pair.seq_gaps!==0)throw Error('voice packet regression '+role);
  }
  await pages[hangup].locator('[data-action=call]').click();
  for(const role of ['master','slave']){
   await pages[role].waitForFunction(()=>state.pair.phase==='ready',{},{timeout:20000});
   results[role].ended=await pages[role].evaluate(()=>state);
  }
  const request=await context.request.post('http://127.0.0.1:9885/api/action',{data:{action:'profile'}});
  results.invalid_action_status=request.status();if(request.status()!==400)throw Error('invalid action accepted');
